application/json.schema:
{
  "title": "JavaScript page to Markdown",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "urls": {
      "title": "URLs",
      "type": "array",
      "description": "Public http(s) pages to render in a real Chromium browser. Up to 500 per run. Pages behind a login are not supported.",
      "editor": "stringList",
      "prefill": [
        "https://quotes.toscrape.com/js/",
        "https://react.dev/"
      ],
      "default": [
        "https://quotes.toscrape.com/js/",
        "https://react.dev/"
      ]
    },
    "waitForSelector": {
      "title": "Wait for CSS selector (optional)",
      "type": "string",
      "description": "Wait until this element exists before reading the page, e.g. .product-list or #results. If it never appears, the page is read anyway and the row says waitForSelectorFound: false.",
      "editor": "textfield"
    },
    "scrollToBottom": {
      "title": "Scroll to load more",
      "type": "boolean",
      "description": "Scroll down the page (up to 8 seconds) so lazy-loaded and infinite-scroll content renders first.",
      "default": false
    },
    "extraWaitMs": {
      "title": "Extra wait after load (ms)",
      "type": "integer",
      "description": "Extra time to wait after the page settles, 0 to 10,000 ms.",
      "minimum": 0,
      "maximum": 10000,
      "default": 0
    },
    "contentScope": {
      "title": "Content to keep",
      "type": "string",
      "description": "main: the page's main content (main/article), or the body without menus, headers and footers. full: the whole rendered body.",
      "editor": "select",
      "enum": [
        "main",
        "full"
      ],
      "enumTitles": [
        "Main content (recommended)",
        "Full page"
      ],
      "default": "main"
    },
    "cssSelector": {
      "title": "CSS selector to extract (optional)",
      "type": "string",
      "description": "Keep only the elements matching this selector, e.g. article or #content. Overrides Content to keep.",
      "editor": "textfield"
    },
    "screenshot": {
      "title": "Save a screenshot of each page",
      "type": "boolean",
      "description": "Save a screenshot of each rendered page to the run's key-value store. The row gets screenshotKey and screenshotUrl. Charged per screenshot.",
      "default": false
    },
    "fullPageScreenshot": {
      "title": "Full-page screenshot",
      "type": "boolean",
      "description": "Capture the whole scrollable page instead of the first screen.",
      "default": false
    },
    "screenshotFormat": {
      "title": "Screenshot format",
      "type": "string",
      "editor": "select",
      "enum": [
        "png",
        "jpeg"
      ],
      "enumTitles": [
        "PNG",
        "JPEG (smaller)"
      ],
      "default": "png",
      "description": "Image format of the screenshot."
    },
    "mobile": {
      "title": "Mobile view",
      "type": "boolean",
      "description": "Render as a phone (390 x 844, mobile user agent) instead of a desktop (1366 x 900).",
      "default": false
    },
    "blockImages": {
      "title": "Skip images, fonts and video while rendering",
      "type": "boolean",
      "description": "Faster and cheaper. Image links still appear in the Markdown. Turned off automatically when a screenshot is requested.",
      "default": true
    },
    "includeLinks": {
      "title": "Include page links",
      "type": "boolean",
      "description": "Add the rendered page's links (URL, text, internal or external) to each row.",
      "default": false
    },
    "maxChars": {
      "title": "Max Markdown characters per page",
      "type": "integer",
      "description": "Longer Markdown is cut and the row says truncated: true.",
      "minimum": 500,
      "maximum": 2000000,
      "default": 200000
    },
    "timeoutSecs": {
      "title": "Timeout per page (seconds)",
      "type": "integer",
      "description": "How long to wait for one page before it is skipped (not charged).",
      "minimum": 10,
      "maximum": 90,
      "default": 20
    },
    "maxConcurrency": {
      "title": "Browser tabs at once (optional)",
      "type": "integer",
      "description": "Pages rendered in parallel. Default is one tab per 512 MB of memory, up to 8.",
      "minimum": 1,
      "maximum": 8
    }
  },
  "required": [
    "urls"
  ]
}

